"""h06 part 1: do section-varying generators WITHOUT plaintext reproduce MS 408's section signal?  (cross-fitted: every held-out folio's text is generated by a model fitted
on the other two folds; the three held-out texts are assembled in manuscript order and pushed through exactly the step-2 section statistics.)

Run: python run_h06_section.py [--seeds 8] [--quick]   (~25 min)
"""
from __future__ import annotations

import argparse
import json
import random
import time

import numpy as np
import pandas as pd

import h06_lib as L

HR, T, CI, R = L.HR, L.T, L.CI, L.R
N_FOLDS = 3
SECTION_ORDER = ["herbal", "recipes", "biological", "pharmaceutical", "cosmo-astro", "other"]
# name -> dict(groups scheme, E per-group engine, U per-group tilt, S pool size)
VARIANTS = {
    "C0g global, no section dependence": dict(groups="none", E=False, U=False, S=0),
    "E per-section engine parameters": dict(groups="section", E=True, U=False, S=0),
    "U3 per-section favoured units, 3 units": dict(groups="section", E=False, U=True, S=0, top=3),
    "U8 per-section favoured units, 8 units": dict(groups="section", E=False, U=True, S=0, top=8),
    "U per-section favoured units": dict(groups="section", E=False, U=True, S=0),
    "P10 per-section pool of 10 types": dict(groups="section", E=False, U=False, S=10),
    "P50 per-section pool of 50 types": dict(groups="section", E=False, U=False, S=50),
    "P200 per-section pool of 200 types": dict(groups="section", E=False, U=False, S=200),
    "EUP10 per-section engine+units+pool 10": dict(groups="section", E=True, U=True, S=10),
    "EUP25 per-section engine+units+pool 25": dict(groups="section", E=True, U=True, S=25),
    "EUP50 per-section engine+units+pool 50": dict(groups="section", E=True, U=True, S=50),
    "EUP100 per-section engine+units+pool 100": dict(groups="section", E=True, U=True, S=100),
    "EUP200 per-section engine+units+pool 200": dict(groups="section", E=True, U=True, S=200),
    "LANG EUP50 by Currier language only": dict(groups="lang", E=True, U=True, S=50),
    "SECLANG EUP50 by section x language": dict(groups="seclang", E=True, U=True, S=50),
    "RAND EUP50 random folio blocks (null)": dict(groups="rand", E=True, U=True, S=50),
    "RAND EUP200 random folio blocks (null)": dict(groups="rand", E=True, U=True, S=200),
    "RAND U random folio blocks, all units (null)": dict(groups="rand", E=False, U=True, S=0),
    "RAND P200 random folio blocks (null)": dict(groups="rand", E=False, U=False, S=200),
}
QUICK = ["C0g global, no section dependence", "U per-section favoured units", "EUP50 per-section engine+units+pool 50", "RAND EUP50 random folio blocks (null)"]


def group_of(entry: dict, idx: int, scheme: str, rand_map: list[str]) -> str:
    sec = entry["cls"] or "other"
    if scheme == "none":
        return "__all__"
    if scheme == "section":
        return sec
    if scheme == "lang":
        return entry["lang"] if entry["lang"] in ("A", "B") else "other"
    if scheme == "seclang":
        return f"{sec}|{entry['lang']}"
    if scheme == "rand":
        return rand_map[idx // 8]
    raise ValueError(scheme)


def fallback_of(g: str, scheme: str) -> str:
    return g.split("|")[0] if scheme == "seclang" and "|" in g else "__all__"


def fit_variant_fold(name: str, spec: dict, entries, train_idx, sh, gm_all, rand_map, seed: int):
    scheme, E, U, S = spec["groups"], spec["E"], spec["U"], spec["S"]
    groups: dict[str, list[str]] = {}
    for i in train_idx:
        groups.setdefault(group_of(entries[i], i, scheme, rand_map), []).extend(entries[i]["words"])
    if scheme == "seclang":                       # section-level parents for fallback
        for i in train_idx:
            groups.setdefault(entries[i]["cls"] or "other", []).extend(entries[i]["words"])
    models = {"__all__": gm_all}
    kk = {"engine": 0, "tilt": 0, "pool": 0}
    if scheme == "none":
        return models, kk
    base = dict(gm_all.params)
    if S > 0:
        base["p_pool"] = 0.2
    free = L.PARAMS if (E and S > 0) else L.PARAMS[:6] if E else ("p_pool",) if S > 0 else ()
    for g, words in sorted(groups.items()):
        gm, chi2 = L.fit_group(sh, words, S, U, free, base, seed=seed, top=spec.get('top'))
        if len(words) < 300 or (scheme == "seclang" and "|" in g and sum(1 for i in train_idx if group_of(entries[i], i, scheme, rand_map) == g) < 3):
            continue                              # too little data: use the fallback
        models[g] = gm
        kk["engine"] += len(free) if len(words) >= 150 else 0
        kk["tilt"] += gm.k_tilt
        kk["pool"] += gm.k_pool
    return models, kk


def stats_one(job):
    L.WSR._one_thread()
    name, seed, docs = job
    st = T.stats_for(docs, n_perm=100, seed=seed)
    X, y, _, _ = T.design(docs)
    st.update(T.shift_null(X, y, seed, stride=4))
    st["nb_langA"], st["nb_langB"] = T.within_language_nb(docs, "A", seed), T.within_language_nb(docs, "B", seed)
    return {"variant": name, "seed": seed, **st}


def main(n_seeds: int = 8, quick: bool = False, workers=None):
    t0 = time.time()
    d = HR.ms_data()
    entries = T.folio_layout(d)
    n = len(entries)
    fold_of = [i % N_FOLDS for i in range(n)]
    rr = random.Random(12345)
    labels = [f"r{i}" for i in range(5)]
    rand_map = [rr.choice(labels) for _ in range(n // 8 + 1)]
    names = QUICK if quick else list(VARIANTS)
    gen = {nm: {s: [None] * n for s in range(1, n_seeds + 1)} for nm in names}
    krows = []
    for k in range(N_FOLDS):
        train_idx = [i for i in range(n) if fold_of[i] != k]
        test_idx = [i for i in range(n) if fold_of[i] == k]
        train_words = [w for i in train_idx for w in entries[i]["words"]]
        sh = L.Shared(train_words, seed=k)
        gm_all, c0 = L.fit_group(sh, train_words, 0, False, L.PARAMS[:6], L.DEFAULT_BASE, seed=k)
        print(f"fold {k}: global engine fitted ({time.time() - t0:.0f}s)", flush=True)
        for nm in names:
            spec = VARIANTS[nm]
            models, kk = fit_variant_fold(nm, spec, entries, train_idx, sh, gm_all, rand_map, seed=100 + k)
            krows.append({"fold": k, "variant": nm, "k_engine_groups": kk["engine"], "k_units": kk["tilt"], "k_pool": kk["pool"],
                          "k_group_specific": kk["engine"] + kk["tilt"] + kk["pool"], "n_groups_fitted": len(models) - 1})
            specs = [{"group": group_of(entries[i], i, spec["groups"], rand_map), "n": len(entries[i]["words"]), "page": i} for i in test_idx]
            fb = {sp["group"]: fallback_of(sp["group"], spec["groups"]) for sp in specs}
            for s in range(1, n_seeds + 1):
                res = L.sv_generate(specs, models, sh, 1000 * s + k, fallback=fb)
                for i, w in zip(test_idx, res):
                    gen[nm][s][i] = w
            print(f"  fold {k} {nm}: {kk} ({time.time() - t0:.0f}s)", flush=True)
    pd.DataFrame(krows).to_csv(L.RESULTS / "section_variant_parameter_counts.csv", index=False)
    jobs = []
    for nm in names:
        for s in range(1, n_seeds + 1):
            docs = T.corpus_from_layout(entries, [w for i in range(n) for w in gen[nm][s][i]])
            jobs.append((nm, s, docs))
    print(f"{len(jobs)} generated corpora -> section statistics ({time.time() - t0:.0f}s)", flush=True)
    rows = CI.pmap(lambda i: stats_one(jobs[i]), range(len(jobs)), workers)
    df = pd.DataFrame(rows)
    df.to_csv(L.RESULTS / ("section_variants_quick.csv" if quick else "section_variants_stats.csv"), index=False)
    print("done", time.time() - t0)


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--seeds", type=int, default=8)
    ap.add_argument("--quick", action="store_true")
    ap.add_argument("--workers", type=int, default=None)
    a = ap.parse_args()
    main(a.seeds, a.quick, a.workers)
